#!/usr/bin/env python3"""Th?ng kê nhanh m?t repo: quy mô, ngôn ng?, manifest, c?u trúc c?p 1-2.Dùng: python repo_stats.py <du?ng-d?n-repo>Ch? d?c, không s?a gì."""import osimport sysfrom collections import CounterIGNORE_DIRS = {    ".git", "node_modules", "bin", "obj", "dist", "build", "target",    "__pycache__", ".venv", "venv", ".idea", ".vscode", ".next", ".gradle",    "vendor", ".dart_tool", "coverage", ".pytest_cache", ".mypy_cache",}MANIFESTS = {    "package.json", "pyproject.toml", "requirements.txt", "setup.py", "go.mod",    "Cargo.toml", "pom.xml", "build.gradle", "build.gradle.kts", "composer.json",    "Gemfile", "Dockerfile", "docker-compose.yml", "docker-compose.yaml",    "Makefile", "global.json", "pubspec.yaml", "CMakeLists.txt",}MANIFEST_SUFFIXES = (".csproj", ".sln", ".fsproj", ".vbproj")CODE_EXT = {    ".py", ".js", ".jsx", ".ts", ".tsx", ".cs", ".razor", ".java", ".kt", ".go",    ".rs", ".php", ".rb", ".c", ".cpp", ".h", ".hpp", ".swift", ".dart", ".sql",    ".html", ".css", ".scss", ".vue", ".svelte", ".sh", ".ps1", ".yml", ".yaml",    ".json", ".md",}MAX_BYTES = 1_000_000def count_lines(path):    try:        if os.path.getsize(path) > MAX_BYTES:            return 0        with open(path, "r", encoding="utf-8") as f:            return sum(1 for _ in f)    except (UnicodeDecodeError, OSError):        return 0def main(root):    root = os.path.abspath(root)    if not os.path.isdir(root):        print(f"Không ph?i thu m?c: {root}")        sys.exit(1)    loc_by_ext, files_by_ext = Counter(), Counter()    manifests = []    for dirpath, dirnames, filenames in os.walk(root):        dirnames[:] = [d for d in dirnames if d not in IGNORE_DIRS]        for name in filenames:            rel = os.path.relpath(os.path.join(dirpath, name), root)            if name in MANIFESTS or name.endswith(MANIFEST_SUFFIXES):                manifests.append(rel)            ext = os.path.splitext(name)[1].lower()            if ext in CODE_EXT:                files_by_ext[ext] += 1                if ext not in {".json", ".md", ".yml", ".yaml"}:                    loc_by_ext[ext] += count_lines(os.path.join(dirpath, name))    total_loc = sum(loc_by_ext.values())    tier = "NH?" if total_loc < 5000 else "V?A" if total_loc < 50000 else "L?N"    print(f"Repo: {root}")    print(f"T?ng LOC mã ngu?n (không tính json/md/yaml): {total_loc} -> quy mô {tier}")    print("\nTheo duôi file (LOC / s? file):")    for ext, loc in loc_by_ext.most_common(10):        print(f"  {ext:8} {loc:8} / {files_by_ext[ext]}")    print("\nManifest / file c?u hình build tìm th?y:")    for m in sorted(manifests):        print(f"  {m}")    if len({os.path.dirname(m) for m in manifests if not m.startswith("Docker")}) > 1:        print("\nLuu ý: manifest ? nhi?u thu m?c -> có th? là monorepo/nhi?u thành ph?n.")    print("\nC?u trúc c?p 1-2:")    for entry in sorted(os.listdir(root)):        if entry in IGNORE_DIRS or entry.startswith("."):            continue        p = os.path.join(root, entry)        print(f"  {entry}{'/' if os.path.isdir(p) else ''}")        if os.path.isdir(p):            for sub in sorted(os.listdir(p))[:12]:                if sub not in IGNORE_DIRS:                    print(f"    {sub}")if __name__ == "__main__":    main(sys.argv[1] if len(sys.argv) > 1 else ".")